import {existsSync,readFileSync,writeFileSync} from 'node:fs';
import {randomInt} from 'node:crypto';
import articles from './humanizer-20260911.mjs';
const date='2026-09-11';
const queuePath=`docs/ziwei-daily-${date}-queue.md`;
if(existsSync(queuePath))throw new Error('Queue already exists; preserve it');
const now=new Date(Date.now()+8*3600000);
if(now.toISOString().slice(0,10)!==date)throw new Error('Wrong Shanghai day');
const first=Math.max(9*60+30,now.getUTCHours()*60+now.getUTCMinutes()+25);
const end=23*60;
if(end-first<60)throw new Error('Too late for a dispersed same-day queue');
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const slots=Array.from({length:30},(_,i)=>{const lo=Math.floor(first+i*(end-first)/30);const hi=Math.floor(first+(i+1)*(end-first)/30);return {time:time(randomInt(lo,Math.max(lo+1,hi))),status:'held_no_qualified_draft',slug:null}});
const assigned=articles.map((a,i)=>{const slot=slots[Math.floor(i*29/(articles.length-1))];slot.status='prepared';slot.slug=a.slug;return {...a,time:slot.time}});
const source=assigned.map((a,i)=>`## ${i+1}. ${a.title}\nslug: \`${a.slug}\`\n\n正文草稿：\n${a.body}\n\n英文标题：${a.enTitle}\n英文描述：${a.enDescription}\n英文正文：\n${a.enBody}`).join('\n\n---\n\n')+'\n';
const queue=`# ${date} 新文队列（${articles.length}/30，未上线不计已发）\n\n时间均为Asia/Shanghai +08:00。晚启动顺延；旧文章与专题页保留。\n\n`+assigned.map((a,i)=>`${String(i+1).padStart(2,'0')}. ${date} ${a.time} - ${a.title} (+08:00)`).join('\n')+'\n\n| 序号 | 状态 | slug | 标题 | 分类 |\n| --- | --- | --- | --- | --- |\n'+assigned.map((a,i)=>`| ${String(i+1).padStart(2,'0')} | 待发布 | ${a.slug} | ${a.title} | ${a.category} |`).join('\n')+'\n';
writeFileSync(`docs/ziwei-daily-${date}-source.md`,source);
writeFileSync(queuePath,queue);
writeFileSync(`docs/article-drafts/${date}-release-plan.json`,JSON.stringify({date,timezone:'Asia/Shanghai',offset:'+08:00',target:30,prepared:articles.length,shortfall:30-articles.length,createdAt:new Date().toISOString(),slots},null,2)+'\n');
console.log(JSON.stringify(assigned.map(a=>({title:a.title,slug:a.slug,time:a.time})),null,2));
